import{_ as o,o as r,c as e,a2 as n}from"./chunks/framework.CHeM0PsO.js";const d=JSON.parse('{"title":"0. 前言","description":"","frontmatter":{"abstract":"","date":"2019/03/31","date_time":"2019/03/31","file_name":"kotlin-coroutines-00-forword","group":"kotlin-coroutines","keywords":"Kotlin 协程 入门","position":89,"tags":"","title":"0. 前言"},"headers":[],"relativePath":"topics/kotlin-coroutines/00-forword.md","filePath":"topics/kotlin-coroutines/00-forword.md","lastUpdated":1785284603000}'),i={name:"topics/kotlin-coroutines/00-forword.md"};function s(a,t,l,p,c,_){return r(),e("div",null,[...t[0]||(t[0]=[n('<p>最近我因缘际会写了<a href="https://www.bennyhuo.com/book/swift-coroutines/" target="_blank" rel="noreferrer"><strong>闲话 Swift 协程</strong></a>和<a href="https://www.bennyhuo.com/book/cpp-coroutines/" target="_blank" rel="noreferrer"><strong>渡劫 C++ 协程</strong></a>系列文章来介绍 Swift 协程和 C++ 协程，写完之后又把它们整理成电子书的形式发布了出来。<strong>破解 Kotlin 协程</strong>系列文章自然也可以成为其中的一员。</p><p>这份前言是 2022 年后补的，文章则主要是 2019 年基于 Kotlin 1.3 撰写的。随着 Kotlin 协程的快速迭代，这些文章中的有些内容已经过时，读者需要在阅读的过程中自行甄别。</p><p>Kotlin 1.3 是在 2018 年底发布的，随着 Kotlin 协程框架的正式发布，Kotlin 官方也终于把语言层面的协程特性扶正了。协程即便在现在也不能算是一个特别容易上手的特性，更何况当时官方自己的文档还一塌糊涂呢。基于当时的情况，我持续地写了十几篇文章来介绍 Kotlin 协程的相关特性以及框架的使用，这也就是大家即将要看到的<strong>破解 Kotlin 协程</strong>系列文章了。</p><p>这些文章的撰写并不容易，因为所有的知识来源基本上就是 Kotlin 标准库和 Kotlin 协程库的源码。你甚至可以想象到那时候官方源码当中的注释都有可能是错的，我也几次向 Kotlin 协程库提了 issue。</p><p>这些文章后来也成为我在 2020 年出版的<a href="https://item.jd.com/12898592.html" target="_blank" rel="noreferrer"><strong>《深入理解 Kotlin 协程》</strong></a>一书的第六章的主要内容基础。</p><blockquote><p><strong>说明</strong> 如果你想要深入了解 Kotlin 协程的运行机制和实现细节，建议直接阅读<a href="https://item.jd.com/12898592.html" target="_blank" rel="noreferrer"><strong>《深入理解 Kotlin 协程》</strong></a>，书中对 Kotlin 协程的原理和实现做了详细的剖析和介绍，甚至带着读者还一步一步完成了一个简化版的协程框架。</p></blockquote>',6)])])}const g=o(i,[["render",s]]);export{d as __pageData,g as default};
